<template><section><div class="rounded-3xl bg-indigo-600 p-8 text-white"><p class="font-bold uppercase tracking-wider text-indigo-200">Your account</p><h1 class="mt-2 text-4xl font-black">Shop, share, and earn from one account.</h1><p class="mt-3 max-w-2xl text-indigo-100">Every customer account is automatically ready for affiliate marketing. Share products you love and earn the commission attached to eligible programs.</p><div class="mt-6 inline-block rounded-xl bg-white/15 px-5 py-3 font-bold">Affiliate marketing is enabled automatically</div></div><h2 class="mt-10 text-xl font-black">Available programs</h2><div class="mt-4 grid gap-4 md:grid-cols-2"><div v-for="p in programs" :key="p.id" class="rounded-2xl border bg-white p-5"><b>{{p.name}}</b><p class="mt-2 text-slate-500">{{p.commissionType==='percentage'?p.commissionRate+'% commission':'Fixed commission'}}</p></div><div v-if="!programs.length" class="rounded-2xl border bg-white p-5 text-slate-500">No affiliate programs are active yet. Check back when products become shareable.</div></div></section></template><script>import api from'../services/api';export default{data(){return{programs:[]}},async mounted(){try{const r=await api.get('/affiliate-programs');this.programs=r.data.data||r.data.programs||[]}catch{}}}}</script>